      { id: "Dhabit 3: Definisi Al-Qur'an", ar: "الضابط الثالث: تعريف القرآن", sub: [{ id: "Kalamullah, diturunkan, berbahasa Arab", ar: "كلام الله المنزل بلفظه العربي" }, { id: "Bernilai ibadah, mutawatir, tertulis di mushaf", ar: "المتعبد بتلاوته المنقول بالتواتر المكتوب في المصاحف" }] }
