    { ar: "التكليم من وراء حجاب", latin: "at-takliim min wara'i hijab", id: "Berbicara dari balik tabir", def: { id: "Allah berbicara hakiki dan didengar langsung tanpa melihat dan tanpa malaikat, seperti kepada Musa.", ar: "سماع كلام الله حقيقة بلا واسطة ملك." } },
    { ar: "روح القدس", latin: "ruhul qudus", id: "Ruhul Qudus", def: { id: "Jibril ‘alaihis-salam, pembawa wahyu yang memberi kehidupan bagi hati.", ar: "جبريل عليه السلام." } },
    { ar: "كُتّاب الوحي", latin: "kuttab al-wahy", id: "Penulis wahyu", def: { id: "Para sahabat yang menulis Al-Qur'an di hadapan Nabi ﷺ; ada enam belas yang disebut.", ar: "الصحابة الذين كتبوا القرآن بين يدي النبي ﷺ." } },
    { ar: "القرآن", latin: "al-Qur'an", id: "Al-Qur'an", def: { id: "Kalamullah yang diturunkan kepada Muhammad ﷺ berlafaz Arab, bernilai ibadah membacanya, mutawatir, tertulis di mushaf.", ar: "كلام الله المنزل على محمد ﷺ بلفظه العربي المتعبد بتلاوته المنقول بالتواتر المكتوب في المصاحف." } },
    { ar: "التواتر", latin: "at-tawatur", id: "Mutawatir", def: { id: "Penukilan oleh jumlah besar dari jumlah besar pada setiap generasi yang mustahil bersepakat dusta.", ar: "نقل جمع غفير عن جمع غفير يمتنع تواطؤهم على الكذب." } },
    { ar: "القراءة الشاذة", latin: "al-qira'ah asy-syadzdzah", id: "Bacaan syadz", def: { id: "Bacaan yang tidak mutawatir sehingga tidak disebut Al-Qur'an, seperti “mutatabi'at” Ibnu Mas'ud.", ar: "قراءة لم تتواتر فلا تسمى قرآنًا." } },
    { ar: "الحديث القدسي", latin: "al-hadits al-qudsi", id: "Hadits qudsi", def: { id: "Hadits yang dinisbatkan Nabi ﷺ kepada Allah; tidak diibadahi dengan membacanya dan tidak mukjizat.", ar: "ما يرويه النبي ﷺ عن ربه، لا يتعبد بتلاوته وليس معجزًا." } }
